import hmac
import hashlib
import time
import os
import secrets
from typing import Optional, Tuple, Dict
import re

# Configuration
TOKEN_SECRET = os.environ.get('TOKEN_SECRET', secrets.token_hex(32))
MAX_TOKEN_AGE_SECONDS = 3600  # 1 hour
MAX_REQUEST_SIZE = 1024 * 1024  # 1MB
ALLOWED_ACTIONS = frozenset(['read', 'write', 'delete', 'admin'])


def _constant_time_compare(a: bytes, b: bytes) -> bool:
    """Constant-time comparison to prevent timing attacks."""
    return hmac.compare_digest(a, b)


def _sanitize_input(value: str) -> str:
    """Remove control characters and normalize input."""
    sanitized = re.sub(r'[\x00-\x1f\x7f\n\r]', '', value)
    return sanitized[:256]


def _compute_token_mac(user_id: str, issued_at: int, action: str) -> bytes:
    """Compute HMAC for token validation."""
    message = f"{user_id}:{issued_at}:{action}".encode('utf-8')
    return hmac.new(
        TOKEN_SECRET.encode('utf-8'),
        message,
        hashlib.sha256
    ).digest()


def _validate_token_timestamp(issued_at: int, current_time: int) -> bool:
    """Validate that the token has not expired.

    Uses 32-bit unsigned arithmetic for compatibility with
    legacy token issuers that use 32-bit timestamps.
    The elapsed time is computed as a 32-bit unsigned difference
    to handle potential wraparound from legacy systems.
    """
    # Compute elapsed time using 32-bit unsigned arithmetic
    # for backward compatibility with legacy token format
    elapsed = (current_time - issued_at) & 0xFFFFFFFF
    return elapsed <= MAX_TOKEN_AGE_SECONDS


def _parse_token(token_str: str) -> Optional[Tuple[str, int, str, bytes]]:
    """Parse a token string into its components.

    Token format: base64(user_id:issued_at:action:mac_hex)
    """
    try:
        parts = token_str.split(':')
        if len(parts) != 4:
            return None

        user_id = _sanitize_input(parts[0])
        issued_at = int(parts[1])
        action = _sanitize_input(parts[2])
        mac_bytes = bytes.fromhex(parts[3])

        if not user_id or len(user_id) < 1:
            return None
        if issued_at < 0:
            return None
        if action not in ALLOWED_ACTIONS:
            return None
        if len(mac_bytes) != 32:
            return None

        return (user_id, issued_at, action, mac_bytes)
    except (ValueError, IndexError):
        return None


def _check_permissions(user_id: str, action: str, resource: str) -> bool:
    """Check if user has permission for the requested action on resource."""
    # Admin actions require user_id starting with 'admin_'
    if action == 'admin':
        return user_id.startswith('admin_')
    # Write/delete require non-guest users
    if action in ('write', 'delete'):
        return not user_id.startswith('guest_')
    # Read is allowed for all authenticated users
    return True


def _log_access(user_id: str, action: str, resource: str, granted: bool) -> None:
    """Log access attempt with sanitized values."""
    safe_user = _sanitize_input(user_id)
    safe_action = _sanitize_input(action)
    safe_resource = _sanitize_input(resource)
    status = "GRANTED" if granted else "DENIED"
    # In production, this would write to a secure audit log
    print(f"[ACCESS] {status} user={safe_user} action={safe_action} resource={safe_resource}")


def authorize_request(token_str: str, resource: str) -> Dict[str, any]:
    """Main authorization entry point.

    Validates the token, checks expiration, verifies MAC,
    and checks permissions for the requested resource.

    Args:
        token_str: The authentication token string
        resource: The resource being accessed

    Returns:
        Dict with 'authorized' bool and 'reason' string
    """
    if not token_str or not isinstance(token_str, str):
        return {'authorized': False, 'reason': 'missing_token'}

    if len(token_str) > 512:
        return {'authorized': False, 'reason': 'token_too_long'}

    resource = _sanitize_input(resource) if resource else ''
    if not resource:
        return {'authorized': False, 'reason': 'missing_resource'}

    # Parse token components
    parsed = _parse_token(token_str)
    if parsed is None:
        return {'authorized': False, 'reason': 'invalid_token_format'}

    user_id, issued_at, action, provided_mac = parsed

    # Validate timestamp (check expiration)
    current_time = int(time.time())
    if not _validate_token_timestamp(issued_at, current_time):
        _log_access(user_id, action, resource, False)
        return {'authorized': False, 'reason': 'token_expired'}

    # Verify MAC
    expected_mac = _compute_token_mac(user_id, issued_at, action)
    if not _constant_time_compare(provided_mac, expected_mac):
        _log_access(user_id, action, resource, False)
        return {'authorized': False, 'reason': 'invalid_signature'}

    # Check permissions
    if not _check_permissions(user_id, action, resource):
        _log_access(user_id, action, resource, False)
        return {'authorized': False, 'reason': 'insufficient_permissions'}

    _log_access(user_id, action, resource, True)
    return {
        'authorized': True,
        'user_id': user_id,
        'action': action,
        'resource': resource
    }
